  groupLabel = '';

  currentlySelected: Selected | null = null;
  CurrentlyMarked: Selected | null = null;

  private static defaultDisplayOptions(): TestViewDisplayOptions { return {
    view: 'medium',
    groupColumn: 'hide',
    bookletColumn: 'show',
    blockColumn: 'show',
    unitColumn: 'hide',
    bookletStatesColumns: [],
    highlightSpecies: false,
    manualChecking: false,
