  isScrollable = false;
  isClosing = false;
  checkedSessionCount = 0;

  quickFilter: string = '';
  quickFilterBoxOpen: boolean = false;

  private readonly messageState = signal<UIMessage[]>([]);
  get messages(): UIMessage[] { return this.messageState(); }
  private appendMessage(message: UIMessage): void {
