export type NativeMonitorEntry<T>={key:string;value:T};
type Compare<T>=(a:NativeMonitorEntry<T>,b:NativeMonitorEntry<T>)=>number;
/** Source uses string-keyed records. Cache each record's shallow view so unrelated
 * tables keep stable entries, including when keys are added or removed in place. */
export class NativeMonitorEntriesView {
 private readonly records=new WeakMap<object,{before:NativeMonitorEntry<unknown>[];result:NativeMonitorEntry<unknown>[];compare:unknown}>();
 readonly transform=<T>(value:Record<string,T>|null|undefined,compare?:Compare<T>|null):NativeMonitorEntry<T>[]|null=>{
  if(value==null)return null;
  const entries=Object.entries(value).map(([key,value])=>({key,value})),old=this.records.get(value);
  if(old&&compare===old.compare&&entries.length===old.before.length&&entries.every((entry,i)=>entry.key===old.before[i].key&&Object.is(entry.value,old.before[i].value)))return old.result as NativeMonitorEntry<T>[];
  const unchanged=old&&entries.length===old.before.length&&entries.every((entry,i)=>entry.key===old.before[i].key&&Object.is(entry.value,old.before[i].value));
  const result=unchanged?old.result as NativeMonitorEntry<T>[]:[...entries];
  if(compare!==null)result.sort(compare??((a,b)=>a.key===b.key?0:a.key<b.key?-1:1));
  this.records.set(value,{before:entries,result,compare});return result;
 };
}
/** The native monitor displays nonnegative remaining minutes as whole numbers.
 * Browser Intl keeps the same grouping and half-expand rounding as Angular's
 * number:1.0-0 formatter without loading its full locale formatter at startup. */
const formatters=new Map<string,Intl.NumberFormat>();
export function formatNativeMonitorMinutes(value:number,locale='en-US'):string{
 let formatter=formatters.get(locale);if(!formatter){formatter=new Intl.NumberFormat(locale,{minimumFractionDigits:0,maximumFractionDigits:0});formatters.set(locale,formatter);}
 return formatter.format(value);
}
import { isBooklet, type TestSession } from '../group-monitor.interfaces';

export class BookletStatesPipe {
  // eslint-disable-next-line class-methods-use-this
  transform(testSession: TestSession, state: string, stateOption: string): { state: string; option: string } | false {
    if (!isBooklet(testSession.booklet)) return false;
    return {
      state: testSession.booklet.states[state]?.label || state,
      option: testSession.booklet.states[state]?.options[stateOption]?.label || stateOption
    };
  }
}
import type { Testlet, TestSession } from '../group-monitor.interfaces';

export class IsCodeClearPipe {
  // eslint-disable-next-line class-methods-use-this
  transform(testSession: TestSession, testlet: Testlet) {
    return testSession.clearedCodes && testSession.clearedCodes.includes(testlet.id);
  }
}import {
  isUnit, type Testlet, type TestSession, type Unit
} from '../group-monitor.interfaces';

export class PositionPipe {
  // eslint-disable-next-line class-methods-use-this
  transform(testSession: TestSession, root: Testlet): string {
    const c = {
      hiddenUnits: 0,
      hasShow: false,
      found: false,
      position: 0
    };
    const countHiddenChildren = (testlet: Testlet): void => {
      let i = 0;
      let child: Testlet | Unit;
      while (child = testlet.children[i++]) {
        if (isUnit(child)) {
          if (child.alias === testSession.current?.unit?.alias) {
            c.found = true;
            if (testSession.current) {
              c.position =
                testSession.current[root.id === '[0]' ? 'indexGlobal' : 'indexAncestor'] + 1 - c.hiddenUnits;
            }
          }
          continue;
        }
        if (child.restrictions.show) {
          c.hasShow = true;
        }
        countHiddenChildren(child);
        if (
          !!child.restrictions.show &&
          testSession.bookletStates &&
          (testSession.bookletStates[child.restrictions.show.if] !== child.restrictions.show.is)
        ) {
          c.hiddenUnits += child.descendantCount;
        }
      }
    };
    countHiddenChildren(root);
    return `${c.position ? `${c.position} / ` : ''}${root.descendantCount - c.hiddenUnits}${c.hasShow ? '*' : ''}`;
  }
}
import { isBooklet, type Testlet, type TestSession } from '../group-monitor.interfaces';

export class TestletvisiblePipe {
  // eslint-disable-next-line class-methods-use-this
  transform(session: TestSession, testlet: Testlet): boolean {
    if (!isBooklet(session.booklet)) return false;
    if (!testlet.restrictions.show) return true;
    const current = (session.bookletStates && session.bookletStates[testlet.restrictions.show.if]) ?
      session.bookletStates[testlet.restrictions.show.if] :
      session.booklet.states[testlet.restrictions.show.if].default;
    return current === testlet.restrictions.show.is;
  }
}
import type { Testlet, TestSession } from '../group-monitor.interfaces';

export class TimeLeftPipe {
  // eslint-disable-next-line class-methods-use-this
  transform(testSession: TestSession, testlet: Testlet): number | false {
    return (testSession.timeLeft !== null) &&
    (testSession.timeLeft[testlet.id] !== undefined) &&
    (testSession.timeLeft[testlet.id] >= 0) ?
      testSession.timeLeft[testlet.id] :
      false;
  }
}
import type { TestSession } from '../group-monitor.interfaces';

export interface TestSessionByDataTestId {
  [testId: string]: TestSession;
}
export interface TestSessionChange {
  personId: string;
  groupName: string;
  personLabel: string;
  mode?: string;
  groupLabel?: string;
  testId: string;
  bookletName?: string;
  testState: {
    [testStateKey: string]: string
  };
  testStateKey?: string;
  testStateValue?: string;
  unitName?: string;
  unitState: {
    [unitStateKey: string]: string
  };
  timestamp: number;
}

export function isSessionChange(arg: any): arg is TestSessionChange {
  return (arg.personId !== undefined) && (arg.timestamp !== undefined) && (arg.groupName !== undefined);
}

export function isSessionChangeArray(arg: any): arg is TestSessionChange[] {
  return Array.isArray(arg) && arg.every(isSessionChange);
}

